begin;
select plan(31);
insert into auth.users(id,email) values
 ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','rubric-a@example.test'),
 ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','rubric-b@example.test');
select public.get_or_create_account_profile('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','rubric-a@example.test',true);
select public.get_or_create_account_profile('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','rubric-b@example.test',true);
select public.get_user_settings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
select public.get_user_settings('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
select ok(public.valid_assessment_rubric(public.default_assessment_rubric()),'default rubric valid');
select ok(not public.valid_assessment_rubric('{}'),'missing criteria invalid');
select ok(not public.valid_assessment_rubric('{"criteria":null}'),'null array invalid');
select ok(not public.valid_assessment_rubric(jsonb_set(public.default_assessment_rubric(),'{criteria,0,weight}','true')),'boolean weight invalid');
select ok(not public.valid_assessment_rubric(jsonb_set(public.default_assessment_rubric(),'{criteria,0,weight}','0')),'zero weight invalid');
select ok(not public.valid_assessment_rubric(jsonb_set(public.default_assessment_rubric(),'{criteria,0,weight}','11')),'weight above ten invalid');
select ok(not public.valid_assessment_rubric(jsonb_set(public.default_assessment_rubric(),'{criteria,0,weight}','1.5')),'fractional weight invalid');
select ok(not public.valid_assessment_rubric(jsonb_set(public.default_assessment_rubric(),'{criteria,0,description}',to_jsonb(E' \n\t'::text))),'blank description invalid');
select ok(not public.valid_assessment_rubric(jsonb_set(public.default_assessment_rubric(),'{criteria,0,description}',to_jsonb(repeat('a',1001)))),'long description invalid');
select ok(not public.valid_assessment_rubric(jsonb_set(public.default_assessment_rubric(),'{criteria,0,name}','"unknown"')),'unknown ID invalid');
select ok(not public.valid_assessment_rubric(jsonb_set(public.default_assessment_rubric(),'{criteria,0,name}','"evidence"')),'duplicate ID invalid');
select throws_ok($$select public.update_user_assessment_settings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',75,'{}')$$,'P0001','invalid_rubric','invalid rubric aborts entire save');
select is((select valuable_threshold from public.settings where user_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),60::numeric,'failed save preserves threshold');
select public.update_user_assessment_settings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',75,jsonb_set(public.legacy_assessment_rubric(),'{criteria,0,weight}','10'));
select is((select rubric#>>'{criteria,0,weight}' from public.settings where user_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'1','other owner unchanged');
select public.submit_fetch_items('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',array['https://rubric.example/one']);
create temporary table rubric_job as select * from public.claim_processing_job('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
create temporary table rubric_reserved as select r.* from rubric_job j cross join lateral public.reserve_analysis(j.user_id,j.id,j.lease_token,0.01) r;
select is((select rubric_snapshot#>>'{criteria,0,weight}' from rubric_reserved),'10','reservation captures custom weight');
select public.update_user_assessment_settings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',90,public.default_assessment_rubric());
select is((select j.rubric_snapshot#>>'{criteria,0,weight}' from public.jobs j join rubric_job r on r.id=j.id),'10','settings edits do not change reserved job');
select is((select r.threshold_snapshot from public.jobs r join rubric_job j on j.id=r.id),75::numeric,'threshold uses same snapshot');
select is((select count(*)::int from rubric_job j cross join lateral public.reserve_analysis('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',j.id,j.lease_token,0.01)),0,'foreign owner cannot reserve job');
update public.jobs set status='failed',processing_stage='invalid_model_output' where id in(select id from rubric_job);
select is((select count(*)::int from public.resume_processing_item('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select item_id from rubric_job))),0,'uncertain reservation cannot be explicitly reset');
update public.jobs set status='processing',lease_expires_at=now()-interval '1 minute' where id in(select id from rubric_job);
create temporary table recovered_rubric_job as select * from public.claim_processing_job('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
select is((select rubric_snapshot#>>'{criteria,0,weight}' from recovered_rubric_job),'10','expired-lease recovery retains original rubric');
select is((select threshold_snapshot from recovered_rubric_job),75::numeric,'recovery retains original threshold');
update rubric_job j set lease_token=r.lease_token from recovered_rubric_job r where r.id=j.id;
select public.save_job_source(j.user_id,j.id,j.lease_token,repeat('Complete evidence passage. ',20)) from rubric_job j;
select public.settle_analysis(user_id,id,0.001) from rubric_reserved;
select public.complete_processing_job(j.user_id,j.id,j.lease_token,
 jsonb_build_object('note','Note','criteria','[]'::jsonb,'score',80,'verdict','valuable','rubric_snapshot',public.default_assessment_rubric()),'[]') from rubric_job j;
select is((select a.rubric_snapshot#>>'{criteria,0,weight}' from public.assessments a join rubric_job j on j.item_id=a.item_id),'10','completion uses authoritative job snapshot, not submitted replacement');
select public.update_user_assessment_settings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',85,null);
select is((select rubric from public.settings where user_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),public.default_assessment_rubric(),'threshold-only update preserves rubric');
select ok(not has_function_privilege('authenticated','public.update_user_assessment_settings(uuid,numeric,jsonb)','execute'),'client cannot invoke settings RPC');
select ok(has_function_privilege('service_role','public.update_user_assessment_settings(uuid,numeric,jsonb)','execute'),'server can invoke settings RPC');
select ok(not has_function_privilege('anon','public.claim_processing_job(uuid)','execute'),'claim grants remain restricted');
select ok(not has_function_privilege('authenticated','public.reserve_analysis(uuid,uuid,uuid,numeric)','execute'),'reservation grants remain restricted');
update public.jobs set status='failed',processing_stage='invalid_model_output' where id in(select id from rubric_job);
update public.items set status='failed' where id in(select item_id from rubric_job);
select is((select count(*)::int from public.resume_processing_item('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select item_id from rubric_job))),1,'explicit fresh analysis permitted after settled charge');
select ok((select j.rubric_snapshot is null and j.threshold_snapshot is null from public.jobs j join rubric_job r on r.id=j.id),'explicit reset clears both rule snapshots');
create temporary table fresh_rubric_job as select * from public.claim_processing_job('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
create temporary table fresh_rubric_reserved as select r.* from fresh_rubric_job j cross join lateral public.reserve_analysis(j.user_id,j.id,j.lease_token,0.01) r;
select is((select rubric_snapshot#>>'{criteria,0,weight}' from fresh_rubric_reserved),'1','fresh analysis uses current weights');
select is((select threshold_snapshot from fresh_rubric_reserved),85::numeric,'fresh analysis uses current threshold');
select * from finish();
rollback;
